const DEVICE = "LoRa_XIAO_CO2_1_D893A8D4DB1C";
// --------------------------------

const YELLOW_MS = 5  * 60 * 1000;  // 5 min
const RED_MS    = 10 * 60 * 1000;  // 10 min

let lastSeen = flow.get(`watchdog_last_seen.${DEVICE}`);
let now = Date.now();

let led, statusText;

if (!lastSeen) {
    // Never received any data this session
    led = "red";
    statusText = "No data received";
} else {
    let ageMs  = now - lastSeen;
    let ageMin = Math.floor(ageMs / 60000);
    let ageSec = Math.floor((ageMs % 60000) / 1000);

    if (ageMs < YELLOW_MS) {
        led = "green";
        statusText = ageMin > 0
            ? `Last seen: ${ageMin} min ago`
            : `Last seen: < 1 min ago`;


    } else if (ageMs < RED_MS) {
        led = "yellow";
        statusText = `STALE — ${ageMin} min ago`;
    } else {
        led = "red";
        statusText = `OFFLINE — ${ageMin} min ago`;
    }
}

return [
    { payload: led        },   // output 1 — LED color
    { payload: statusText }    // output 2 — status text
];

