const action     = msg.payload;
const device     = flow.get('cal_device');
const tempF      = flow.get('cal_temp_f') || 0;
const altFt      = flow.get('cal_alt_ft') || 1344;

if (!device) {
    node.warn('No device selected');
    return null;
}

let command = { target: device };

if (action === 'set_temp') {
    // SCD41 offset is always positive - it always subtracts this from readings
    // Convert °F difference to °C difference (divide by 1.8, NOT subtract 32)
    const absF = Math.abs(parseFloat(tempF) || 0);
    const tempC = parseFloat((absF / 1.8).toFixed(2));
    command.temp_offset = tempC;
    node.status({ fill:'blue', shape:'dot',
        text: `Set temp offset ${absF}°F (${tempC}°C) → ${device}` });

} else if (action === 'get_temp') {
    command.get_temp_offset = true;
    node.status({ fill:'blue', shape:'dot',
        text: `Get temp offset ← ${device}` });

} else if (action === 'set_alt') {
    // Convert feet to meters
    const altM = Math.round(altFt / 3.28084);
    command.altitude = altM;
    node.status({ fill:'blue', shape:'dot',
        text: `Set altitude ${altFt}ft (${altM}m) → ${device}` });

} else if (action === 'get_alt') {
    command.get_altitude = true;
    node.status({ fill:'blue', shape:'dot',
        text: `Get altitude ← ${device}` });
}

msg.payload = JSON.stringify({
    message: JSON.stringify(command)
});

return msg;

const parts = msg.topic.split('/');
const device = parts[1] || 'unknown';
const field = parts[2] || 'unknown';

const shortName = device.replace('LoRa_XIAO_CO2_', 'XIAO ');
const val = parseFloat(msg.payload);

let display;
if (field.startsWith('temp_offset')) {
    const valF = parseFloat((val * 1.8).toFixed(2));
    display = `${shortName} — ${field}: ${val}°C (${valF}°F)`;
} else if (field.startsWith('altitude')) {
    const valFt = Math.round(val * 3.28084);
    display = `${shortName} — ${field}: ${val}m (${valFt}ft)`;
} else {
    display = `${shortName} — ${field}: ${val}`;
}

msg.payload = display;
return msg;

const device = flow.get('cal_device');

if (!device) {
    node.warn('No device selected');
    node.status({ fill:'red', shape:'dot', text:'No device selected' });
    return null;
}

const command = { target: device, ota: true };

const payload = JSON.stringify({
    message: JSON.stringify(command)
});

node.status({ fill:'blue', shape:'dot',
    text: `OTA triggered → ${device}` });

// Route: output 1 = local (HomePi), output 2 = Nevada (MushRmPi)
const isLocal = device === 'LoRa_XIAO1_2C02A7D4DB1C';

if (isLocal) {
    return [{ payload }, null];
} else {
    return [null, { payload }];
}
